fn solve(n: i8) -> i8 {
    // Compute the integer quotient of n / 3 (floor division for positive n)
    let q = n / 3;
    // If n is exactly divisible by 3, return 2*q; otherwise return 2*q + 1
    if n % 3 == 0 {
        2 * q
    } else {
        2 * q + 1
    }
}

